package io.knowledgebrain.activity;
import java.util.*;import org.junit.jupiter.api.Test;import static org.junit.jupiter.api.Assertions.*;
import io.knowledgebrain.contracts.learning.roadmap.v1.RoadmapEventEnvelopeV1;
import io.knowledgebrain.contracts.content.question.v1.*;
import io.knowledgebrain.contracts.content.decision.v1.*;
import io.knowledgebrain.contracts.content.recordconcepts.v1.*;
class ContentActivityTest extends ActivityFixtures {
 @Test void allContentFactsAndAssociationParentIdentityRemainIndependent()throws Exception{for(var kind:List.of("BOOKMARK","QUESTION","DECISION","RECORD_CONCEPTS")){var wire=wire(kind,id());var e=ActivityEvent.decode(ActivityEvent.TOPICS.get(kind),wire);assertEquals("content",ActivityEvent.group(kind));assertNotNull(e.content());assertNull(e.planning());assertNull(e.roadmapId());assertTrue(ActivityEvent.target(e));assertEquals(0,e.durationSeconds());ActivityEvent.transport(ActivityEvent.TOPICS.get(kind),wire,e.aggregateId().toString(),headers(e));if(kind.equals("RECORD_CONCEPTS")){assertNotEquals(e.aggregateId(),e.content().recordId());assertEquals(7,e.content().recordVersion());assertTrue(e.content().concepts().isEmpty());assertTrue(e.targetPath().contains("/record-concepts/BOOKMARK/"));}else assertEquals(e.aggregateId(),e.content().recordId());}}
 @Test void malformedBodyStateAndRequiredManualStatusContentAreRejected()throws Exception{var env=RoadmapEventEnvelopeV1.parseFrom(wire("QUESTION",id()));var p=QuestionChangedPayloadV1.parseFrom(env.getPayload());for(var bad:List.of(p.toBuilder().setAnswer(" "),p.toBuilder().setStatus("CLOSED"),p.toBuilder().setVisibility("PUBLIC"),p.toBuilder().setContext("x".repeat(16385)),p.toBuilder().setQuestionId(id().toString()),p.toBuilder().setUpdatedAt("2000-01-01T00:00:00Z"),p.toBuilder().setState("RETIRED"))){assertThrows(IllegalArgumentException.class,()->ActivityEvent.decode(ActivityEvent.TOPICS.get("QUESTION"),env.toBuilder().setPayload(bad.build().toByteString()).build().toByteArray()));}var archived=p.toBuilder().setVersion(2).setState("RETIRED").build();var e=ActivityEvent.decode(ActivityEvent.TOPICS.get("QUESTION"),env.toBuilder().setEventType("QuestionRetired").setPayload(archived.toByteString()).build().toByteArray());assertEquals("ANSWERED",e.content().status());assertEquals("Pinned answer",e.content().answer());assertEquals("RETIRED",e.state());var d=RoadmapEventEnvelopeV1.parseFrom(wire("DECISION",id()));var dp=DecisionChangedPayloadV1.parseFrom(d.getPayload());assertThrows(IllegalArgumentException.class,()->ActivityEvent.decode(ActivityEvent.TOPICS.get("DECISION"),d.toBuilder().setPayload(dp.toBuilder().setRationale("").build().toByteString()).build().toByteArray()));}
 @Test void fullOrderedLinksKeepOriginalIdsAndRejectDuplicatesOrForeignKinds()throws Exception{var env=RoadmapEventEnvelopeV1.parseFrom(wire("RECORD_CONCEPTS",id()));var p=RecordConceptsChangedPayloadV1.parseFrom(env.getPayload());var a=RecordConceptLinkV1.newBuilder().setLinkId(id().toString()).setConceptId(id().toString()).build();var b=RecordConceptLinkV1.newBuilder().setLinkId(id().toString()).setConceptId(id().toString()).build();var wire=env.toBuilder().setPayload(p.toBuilder().addLinks(a).addLinks(b).build().toByteString()).build().toByteArray();var e=ActivityEvent.decode(ActivityEvent.TOPICS.get("RECORD_CONCEPTS"),wire);assertEquals(List.of(UUID.fromString(a.getConceptId()),UUID.fromString(b.getConceptId())),e.content().concepts().stream().map(ActivityEvent.Link::conceptId).toList());for(var bad:List.of(p.toBuilder().addLinks(a).addLinks(a),p.toBuilder().setRecordType("NOTE"),p.toBuilder().setRecordState("RETIRED"),p.toBuilder().setRecordVersion(0),p.toBuilder().setAssociationId(id().toString()))){assertThrows(IllegalArgumentException.class,()->ActivityEvent.decode(ActivityEvent.TOPICS.get("RECORD_CONCEPTS"),env.toBuilder().setPayload(bad.build().toByteString()).build().toByteArray()));}assertThrows(IllegalArgumentException.class,()->ActivityEvent.transport(ActivityEvent.TOPICS.get("RECORD_CONCEPTS"),wire,e.content().recordId().toString(),headers(e)));}
 @Test void oldDurableJsonIsReadableWithoutInventingContentFacts(){var e=ActivityEvent.decode(ActivityEvent.TOPICS.get("TASK"),wire("TASK",id()));var json=tools.jackson.databind.json.JsonMapper.builder().build();var tree=(tools.jackson.databind.node.ObjectNode)json.valueToTree(e);tree.remove("content");assertEquals(e,json.treeToValue(tree,ActivityEvent.class));}
 @Test void contentFiltersKeepSpaceKindAndCursorBinding(){var space=id();var params=ActivityQueryTest.params("kind","RECORD_CONCEPTS","timezone","UTC");var q=ActivityQuery.parse(space,params);var e=ActivityEvent.decode(ActivityEvent.TOPICS.get("RECORD_CONCEPTS"),wire("RECORD_CONCEPTS",space));params.put("before",new String[]{q.cursor(e)});assertEquals(e.eventId(),ActivityQuery.parse(space,params).event());assertThrows(RuntimeException.class,()->ActivityQuery.parse(id(),params));params.put("kind",new String[]{"BOOKMARK"});assertThrows(RuntimeException.class,()->ActivityQuery.parse(space,params));}
}
